import { budgetStatus } from '../../../src/core/cost-budget.mjs';
import { isInContainer } from '../../../src/core/remote-access.mjs';
import { budgetWindowSavings } from '../../../src/core/stats.mjs';
import process from 'node:process';
import { bearerMatches, drainServer } from '../../server.mjs';

export function register(app) {

// POST /api/drain: drain without exiting (a platform about to stop the container asks first, so
// the stop itself is quick). From inside the container, or with WORCA_HEARTBEAT_TOKEN as Bearer.
app.post('/api/drain', async (req, res) => {
  const hbToken = String(process.env.WORCA_HEARTBEAT_TOKEN || '').trim();
  if (!isInContainer(req) && !(hbToken && bearerMatches(req.headers.authorization, hbToken))) {
    return res.status(403).json({ error: 'forbidden: drain only from inside the container or with the heartbeat token' });
  }
  const result = await drainServer({ reason: 'request' });
  res.json({ ok: true, draining: true, ...result });
});

app.get('/api/budget', (_req, res) => {
  const budget = budgetStatus();
  // The account menu's spend card ("Saved") rides on this snapshot (money-saved design §10).
  // Additive and best-effort: a failed savings read must never cost the gate figures the
  // New-view Start button and every cost banner key on, so it degrades to nulls instead.
  let savings = { windowHumanHours: null, windowSavedUsd: null };
  try { savings = budgetWindowSavings(budget); } catch { /* keep the nulls */ }
  res.json({ ...budget, ...savings });
});
}
